function build(input={}){const p=input&&typeof input==='object'?input:{},resolved=inherited(()=>base.resolve(p.diagnosis)),record=resolved&&records.get(resolved.key);if(!record)return inherited(()=>base.build(input));const age=p.age===undefined||p.age===null||p.age===''?'unknown':p.age;if(!Object.hasOwn(base.ages,age))return {ok:false,code:'AGE_INVALID',message:'Selecione uma faixa etária válida.'};const previous=inherited(()=>base.build({...p,age}));if(!previous?.ok)return previous;if(p.reviewed!==true&&p.danger!=='yes'&&!(age==='u3m'&&p.fever==='yes'))return {ok:false,code:'REVIEW_REQUIRED',message:'Confirme a avaliação do diagnóstico pela equipe. O site não decide alta.'};const f=data.families[record.family],sections=sectionsFor(record,age),emergency=f.urgent||p.danger==='yes'||age==='u3m'||previous.mode==='urgent';if(emergency){const reasons=[];if(f.urgent)reasons.push('Foi selecionada uma infecção sem resposta adequada ao tratamento. Procure reavaliação urgente; esta ficha não autoriza esperar em casa.');if(age==='u3m')reasons.push('Infecção urinária nesta idade requer avaliação pediátrica imediata, inclusive sem febre.');if(p.danger==='yes')reasons.push('Foi informado sinal de gravidade: procure atendimento imediatamente.');if(previous.mode==='urgent'&&!reasons.length)reasons.push('A avaliação exige atendimento urgente. Siga imediatamente o encaminhamento da equipe.');sections.unshift({title:'ATENDIMENTO URGENTE',items:[...new Set(reasons)]});}const clean=(v,n)=>typeof v==='string'?v.replace(/[\u0000-\u001f\u007f]/g,' ').trim().slice(0,n):'',notes=clean(p.notes,1400),plan=clean(p.returnPlan,200);if(notes)sections.push({title:'COMPLEMENTO DA CONSULTA',items:[notes]});if(plan)sections.find(s=>s.title==='QUANDO REAVALIAR').items.push('Retorno combinado: '+plan);const topic=topics.find(t=>t.key===record.key),text='ORIENTAÇÕES AOS PAIS — '+topic.label+'\nFaixa etária: '+base.ages[age]+'\n\n'+sections.map((s,i)=>(i+1)+'. '+s.title+'\n'+s.items.map(x=>'• '+x).join('\n')).join('\n\n');return {...previous,ok:true,mode:emergency?'urgent':'guidance',topic:topic.key,label:topic.label,sections,refs:[...f.refs],text,warnings:emergency?['Necessidade de avaliação urgente; esta ficha não autoriza alta.']:[],effectiveAgeBand:age,directedGuidance:true};}
